class Solution:
    def validSubarrays(self, nums: List[int], k: int, queries: List[List[int]]) -> List[bool]:
        res = []
        for l, r in queries:
            cnt = {}
            for i in range(l, r + 1):
                cnt[nums[i]] = cnt.get(nums[i], 0) + 1
            res.append(len(cnt) == k and all(v % 2 == 0 for v in cnt.values()))
        return res

