class Solution {
public:
    vector<bool> validSubarrays(vector<int>& nums, int k, vector<vector<int>>& queries) {
        vector<bool> res;
        for (auto& q : queries) {
            unordered_map<int,int> cnt;
            for (int i = q[0]; i <= q[1]; i++) cnt[nums[i]]++;
            bool ok = (int)cnt.size() == k;
            for (auto& [v, c] : cnt) if (c % 2) { ok = false; break; }
            res.push_back(ok);
        }
        return res;
    }
};

