class Solution {
public:
    vector<bool> validSubarrays(vector<int>& nums, int k, vector<vector<int>>& queries) {
        int n = nums.size(), q = queries.size();
        int block = max(1, (int)(n / max(1.0, sqrt((double)q))));
        vector<int> order(q);
        iota(order.begin(), order.end(), 0);
        sort(order.begin(), order.end(), [&](int a, int b) {
            int ba = queries[a][0] / block, bb = queries[b][0] / block;
            if (ba != bb) return ba < bb;
            return (ba & 1) ? queries[a][1] > queries[b][1] : queries[a][1] < queries[b][1];
        });
        int mx = *max_element(nums.begin(), nums.end());
        vector<int> freq(mx + 1, 0);
        int distinct = 0, odd = 0, curL = 0, curR = -1;
        auto add = [&](int i) {
            int v = nums[i];
            if (freq[v] == 0) distinct++;
            else if (freq[v] % 2) odd--; else odd++;
            freq[v]++;
        };
        auto remove = [&](int i) {
            int v = nums[i];
            freq[v]--;
            if (freq[v] == 0) distinct--;
            else if (freq[v] % 2) odd++; else odd--;
        };
        vector<bool> ans(q);
        for (int qi : order) {
            int l = queries[qi][0], r = queries[qi][1];
            while (curL > l) add(--curL);
            while (curR < r) add(++curR);
            while (curL < l) remove(curL++);
            while (curR > r) remove(curR--);
            ans[qi] = (distinct == k && odd == 0);
        }
        return ans;
    }
};

