class Solution {
    public boolean[] validSubarrays(int[] nums, int k, int[][] queries) {
        int n = nums.length, q = queries.length;
        int block = Math.max(1, (int) (n / Math.max(1.0, Math.sqrt(q))));
        Integer[] order = new Integer[q];
        for (int i = 0; i < q; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> {
            int ba = queries[a][0] / block, bb = queries[b][0] / block;
            if (ba != bb) return ba - bb;
            return (ba % 2 == 1) ? queries[b][1] - queries[a][1] : queries[a][1] - queries[b][1];
        });
        int mx = 0;
        for (int x : nums) mx = Math.max(mx, x);
        int[] freq = new int[mx + 1];
        int[] cur = {0, -1};
        int[] agg = {0, 0};
        java.util.function.IntConsumer add = i -> {
            int v = nums[i];
            if (freq[v] == 0) agg[0]++;
            else if (freq[v] % 2 == 1) agg[1]--; else agg[1]++;
            freq[v]++;
        };
        java.util.function.IntConsumer remove = i -> {
            int v = nums[i];
            freq[v]--;
            if (freq[v] == 0) agg[0]--;
            else if (freq[v] % 2 == 1) agg[1]++; else agg[1]--;
        };
        boolean[] ans = new boolean[q];
        for (int qi : order) {
            int l = queries[qi][0], r = queries[qi][1];
            while (cur[0] > l) add.accept(--cur[0]);
            while (cur[1] < r) add.accept(++cur[1]);
            while (cur[0] < l) remove.accept(cur[0]++);
            while (cur[1] > r) remove.accept(cur[1]--);
            ans[qi] = (agg[0] == k && agg[1] == 0);
        }
        return ans;
    }
}

