var validSubarrays = function(nums, k, queries) {
    const n = nums.length, q = queries.length;
    const block = Math.max(1, Math.floor(n / Math.max(1, Math.sqrt(q))));
    const order = [...Array(q).keys()].sort((a, b) => {
        const ba = Math.floor(queries[a][0] / block), bb = Math.floor(queries[b][0] / block);
        if (ba !== bb) return ba - bb;
        return (ba % 2 === 1) ? queries[b][1] - queries[a][1] : queries[a][1] - queries[b][1];
    });
    const mx = Math.max(...nums);
    const freq = new Array(mx + 1).fill(0);
    let distinct = 0, odd = 0, curL = 0, curR = -1;
    const add = i => {
        const v = nums[i];
        if (freq[v] === 0) distinct++;
        else if (freq[v] % 2 === 1) odd--; else odd++;
        freq[v]++;
    };
    const remove = i => {
        const v = nums[i];
        freq[v]--;
        if (freq[v] === 0) distinct--;
        else if (freq[v] % 2 === 1) odd++; else odd--;
    };
    const ans = new Array(q).fill(false);
    for (const qi of order) {
        const [l, r] = queries[qi];
        while (curL > l) add(--curL);
        while (curR < r) add(++curR);
        while (curL < l) remove(curL++);
        while (curR > r) remove(curR--);
        ans[qi] = (distinct === k && odd === 0);
    }
    return ans;
};
